from fractions import Fraction as Q
import math
# Sparse exact rational polynomials in (z,w); scale all rates by a>0.
def add(*ps):
 r={}
 for p in ps:
  for k,v in p.items(): r[k]=r.get(k,Q(0))+v
 return {k:v for k,v in r.items() if v}
def scale(p,c): return {k:v*c for k,v in p.items() if v*c}
def mul(p,q):
 r={}
 for (i,j),v in p.items():
  for (k,l),u in q.items(): r[(i+k,j+l)]=r.get((i+k,j+l),Q(0))+v*u
 return {k:v for k,v in r.items() if v}
def power(p,n):
 r={(0,0):Q(1)}
 for _ in range(n): r=mul(r,p)
 return r
one={(0,0):Q(1)}; z={(1,0):Q(1)}; w={(0,1):Q(1)}
p=add(z,one)
A=add(power(p,2),mul(add(scale(w,2),scale(power(w,2),-2)),p),scale(power(w,2),4))
D=add(mul(add(one,w),z),one,scale(w,-1))
res=add(mul(add(one,w),power(p,3)),scale(mul(A,D),-1),scale(mul(power(w,3),power(add(z,scale(one,-1)),2)),-2))
assert res=={}
# exp(1)>5/2 implies q>6/7, hence minimum polynomial<-1/49.
q_lower=Q(6,7)
minimum_upper=1-(1+q_lower/2)**2/2
assert minimum_upper==Q(-1,49)
q=2*math.tanh(.5); d=1/q+.5
minimum=1-(1+q/2)**2/2
free=math.exp(-d)*minimum
exact=math.exp(-d*math.e)
assert free<0<exact
assert 8*34*35//2==4760
assert 4760+312+96==5168
results={'exact_transfer_residual_polynomial':{},'witness_polynomial_exact_upper':str(minimum_upper),'witness':{'t':-1,'q':q,'d':d,'polynomial':minimum,'Fhat':free,'F_exact':exact},'factor_B':4760,'partial_subtotal_B':5168}
